public long countTriplets(List<Long> arr, long r) {
    int n = arr.size();
    long count = 0;
    for (int i = 0; i < n; i++) {
        for (int j = i + 1; j < n; j++) {
            if (arr.get(j) != arr.get(i) * r) continue;
            for (int k = j + 1; k < n; k++) {
                if (arr.get(k) == arr.get(j) * r) {
                    count++;
                }
            }
        }
    }
    return count;
}

