def count_triplets(arr: list[int], r: int) -> int:
    n = len(arr)
    count = 0
    for i in range(n):
        for j in range(i + 1, n):
            if arr[j] != arr[i] * r:
                continue
            for k in range(j + 1, n):
                if arr[k] == arr[j] * r:
                    count += 1
    return count

