public long countTriplets(List<Long> arr, long r) {
    Map<Long, Long> left = new HashMap<>();
    Map<Long, Long> right = new HashMap<>();
    for (long a : arr) {
        right.merge(a, 1L, Long::sum);
    }
    long count = 0;
    for (long a : arr) {
        right.merge(a, -1L, Long::sum);
        long c1 = (a % r == 0) ? left.getOrDefault(a / r, 0L) : 0L;
        long c2 = right.getOrDefault(a * r, 0L);
        count += c1 * c2;
        left.merge(a, 1L, Long::sum);
    }
    return count;
}
